    power: "sensor.terrassen_pool_power",
    runtime: "sensor.poolpumpe_koeretid_i_dag",
    goal: "input_number.pool_pumpe_normal_timer_pr_dag",
    energy: "sensor.poolpumpe_forbrug_i_dag",
    cost: "sensor.poolpumpe_pris_i_dag",
    afterPending: "input_boolean.pool_efterbad_venter",
    terrace: "binary_sensor.terrasse_syd_person_detected",
    automatic: "input_boolean.pool_automation_aktiv",
    pause: "input_boolean.pool_pumpe_tvangspause_aktiv",
    mode: "input_select.pool_pumpe_manuel_override_varighed",
    manualTimer: "timer.pool_pumpe_manuel_override",
