var HAElectricityPriceCardEditor = class extends HTMLElement {
  setConfig(config) {
    this._config = config || {};
    this._render();
  }
  set hass(hass) {
    this._hass = hass;
    if (!this.childElementCount) this._render();
  }
  _change(key, value) {
    this._config = { ...this._config, [key]: value };
    this.dispatchEvent(
      new CustomEvent("config-changed", {
        detail: { config: this._config },
        bubbles: true,
        composed: true
      })
    );
  }
  _render() {
    if (!this._config) return;
    this.innerHTML = `<style>.row{display:grid;grid-template-columns:150px 1fr;align-items:center;gap:12px;margin:12px 0}select,input{width:100%;padding:8px;border:1px solid var(--divider-color);border-radius:8px;background:var(--card-background-color);color:var(--primary-text-color)}</style>
      <div class="row"><label>Datakilde</label><select data-key="source"><option value="auto">Automatisk</option><option value="stromligning">Str\xF8mligning</option><option value="energidataservice">Energi Data Service</option></select></div>
      <div class="row"><label>Str\xF8mligning pris</label><input data-key="stromligning_current"></div>
      <div class="row"><label>Str\xF8mligning i morgen</label><input data-key="stromligning_tomorrow"></div>
      <div class="row"><label>Str\xF8mligning forecast</label><input data-key="stromligning_forecast"></div>
      <div class="row"><label>Energi Data Service</label><input data-key="energidataservice"></div>
      <div class="row"><label>Desktoph\xF8jde (px)</label><input data-key="desktop_height" type="number" min="350" max="560" step="10"></div>
      <div class="row"><label>Vis titel og aktuel pris</label><input data-key="show_header" type="checkbox"></div>
      <div class="row"><label>Udfyld tilg\xE6ngelig h\xF8jde</label><input data-key="fill_height" type="checkbox"></div>
      <div class="row"><label>Animer priser over 6 kr</label><input data-key="high_price_animation" type="checkbox"></div>
      <div class="row"><label>Ignor\xE9r reduceret bev\xE6gelse</label><input data-key="force_price_animation" type="checkbox"></div>`;
    this.querySelectorAll("select,input").forEach((el) => {
      if (el.type === "checkbox")
        el.checked = el.dataset.key === "high_price_animation" ? this._config.high_price_animation !== false : Boolean(this._config[el.dataset.key]);
      else el.value = this._config[el.dataset.key] || (el.dataset.key === "source" ? "auto" : "");
      el.onchange = () => this._change(el.dataset.key, el.type === "checkbox" ? el.checked : el.value);
    });
  }
};
