    const head = units ? `<header class="lcd-head"><b>${escapeHtml(title)}</b></header>` : `<header class="lcd-rule"><i></i><b>${escapeHtml(title)}</b><i></i></header>`;
    const prev = frame.page > 0 ? '<i class="lcd-tri is-left"></i>' : "<i></i>";
